const all = await items.list();
const j = await jira.listItems();
const jm = Object.fromEntries(j.map(x=>[x.id,x]));
return all.map(i=>{ if(i.gone) return {id:i.id,gone:i.reason};
const x:any=jm[i.id];
if(x&&!x.gone) return {key:i.id,type:x.issueType,summary:x.summary,status:x.status.name,assignee:x.assignee?.name??null,points:x.points,labels:x.labels,desc:x.description.slice(0,300),lastComment:x.comments.at(-1)?{a:x.comments.at(-1).author,b:x.comments.at(-1).body.slice(0,200),at:x.comments.at(-1).at}:null,nComments:x.comments.length};
return {id:i.id,title:i.title,text:i.text.slice(0,600)};});

